    "msg.47eff7d7b651": "ma identyczne bajty do",
    "msg.f87725a7b3b0": "Użyj hasła o co najmniej 12 znakach.",
    "msg.fca2a59c57d7": "Nieobsługiwany zaszyfrowany pojemnik.",
    "msg.203e53ecacad": "Nieprawidłowe zaszyfrowane wymiary kontenera.",
    "msg.c944ec3fce18": "Złe hasło lub uszkodzona kopia zapasowa.",
